style.css:
@-moz-document domain("1password.com"), domain("my.1password.com") {
/* General body and html overrides */
  html, body {
    background-color: #121212 !important;
    color: #e0e0e0 !important;
  }

  /* Text elements */
  p, span, div, li, td, th, label {
    color: #e0e0e0 !important;
  }

  h1, h2, h3, h4, h5, h6 {
    color: #ffffff !important;
  }

  /* Links */
  a, a:visited {
    color: #8ab4f8 !important;
  }

  a:hover {
    color: #a8c7fa !important;
  }

  /* Buttons */
  button, input[type="button"], input[type="submit"], .btn, .button {
    background-color: #1e1e1e !important;
    color: #ffffff !important;
    border: 1px solid #333333 !important;
  }

  button:hover, input[type="button"]:hover, input[type="submit"]:hover, .btn:hover, .button:hover {
    background-color: #292929 !important;
  }

  /* Inputs and forms */
  input, textarea, select {
    background-color: #1e1e1e !important;
    color: #e0e0e0 !important;
    border: 1px solid #333333 !important;
  }

  input:focus, textarea:focus, select:focus {
    border-color: #8ab4f8 !important;
    box-shadow: 0 0 0 2px rgba(138, 180, 248, 0.3) !important;
  }

  /* Headers, nav, footers */
  header, nav, footer, .header, .nav, .footer {
    background-color: #0a0a0a !important;
    color: #e0e0e0 !important;
  }

  /* Cards, modals, panels */
  .card, .panel, .modal, .dialog, div[role="dialog"] {
    background-color: #1e1e1e !important;
    color: #e0e0e0 !important;
    border: 1px solid #333333 !important;
  }

  /* Tables */
  table {
    background-color: #1e1e1e !important;
  }

  tr:nth-child(even) {
    background-color: #181818 !important;
  }

  th {
    background-color: #0a0a0a !important;
  }

  /* Lists */
  ul, ol {
    background-color: #121212 !important;
  }

  /* Override common light backgrounds */
  [class*="bg-white"], [class*="bg-light"], [style*="background: white"], [style*="background-color: white"], [style*="background: #fff"], [style*="background-color: #fff"] {
    background-color: #121212 !important;
  }

  /* Images and icons: Prevent inversion if using filters elsewhere (optional) */
  img, svg, .icon {
    filter: brightness(0.9) !important; /* Slight adjustment for visibility in dark mode */
  }

  /* Scrollbars (WebKit browsers) */
  ::-webkit-scrollbar {
    background: #121212 !important;
  }

  ::-webkit-scrollbar-thumb {
    background: #333333 !important;
  }
}
